CREATE TABLE bell_profiles (kind TEXT NOT NULL, pair INTEGER NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, PRIMARY KEY(kind,pair));
CREATE TABLE curator_slots (day INTEGER PRIMARY KEY CHECK(day IN (1,4)), enabled INTEGER NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, title TEXT NOT NULL);
CREATE TRIGGER revision_bell_profiles_insert AFTER INSERT ON bell_profiles BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
CREATE TRIGGER revision_bell_profiles_update AFTER UPDATE ON bell_profiles BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
CREATE TRIGGER revision_bell_profiles_delete AFTER DELETE ON bell_profiles BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
CREATE TRIGGER revision_curator_slots_insert AFTER INSERT ON curator_slots BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
CREATE TRIGGER revision_curator_slots_update AFTER UPDATE ON curator_slots BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
CREATE TRIGGER revision_curator_slots_delete AFTER DELETE ON curator_slots BEGIN INSERT INTO meta(key,value) VALUES('revision',lower(hex(randomblob(16)))) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END;
